import { memo, useState, useCallback } from "react";
import { useNavigate } from "react-router-dom";
import { useTheme } from "@mui/material/styles";
import BottomNavigationAction from "@mui/material/BottomNavigationAction";
import FavoriteIcon from "@mui/icons-material/Favorite";
import SearchIcon from "@mui/icons-material/Search";
import { useLocation } from "react-router-dom";

import { globalThemes } from "theme";
import { routes } from "routes";
import { Theme } from "utils/constants";

import * as S from "./styled";

const Navigation = () => {
  const theme = useTheme();
  let location = useLocation();
  const navigate = useNavigate();

  const [value, setValue] = useState(location.pathname);

  const handleNavigate = useCallback(
    (event: React.SyntheticEvent<Element, Event>, newValue: string) => {
      setValue(newValue);
      if (newValue === routes.SEARCH) navigate(-1);
      navigate(newValue);
    },
    [navigate, setValue]
  );

  return (
    <S.CustomBottomNavigation
      showLabels
      value={value}
      onChange={handleNavigate}
      style={{
        boxShadow:
          theme.palette.mode === Theme.Light
            ? globalThemes.boxShadow.light
            : globalThemes.boxShadow.dark,
      }}
    >
      <BottomNavigationAction
        value={routes.SEARCH}
        label="Search"
        icon={<SearchIcon />}
      />
      <BottomNavigationAction
        value={routes.FAVORITE}
        label="Favorite"
        icon={<FavoriteIcon />}
      />
    </S.CustomBottomNavigation>
  );
};

export default memo(Navigation);
