import { memo, lazy, Suspense } from "react";
import { Routes as Switch, Route } from "react-router-dom";

import Layout from "components/Layout";
import Loading from "components/Loading";
import { HomeIcon } from "assets/images";

import { routes } from ".";

const Search = lazy(() => import("../containers/SearchPage"));
const Favorite = lazy(() => import("../containers/FavoritePage"));
const Detail = lazy(() => import("../containers/DetailPage"));
const NotFound = lazy(() => import("../containers/NotFoundPage"));

const Routes = () => {
  return (
    <Suspense fallback={<Loading />}>
      <Switch>
        <Route
          path={routes.SEARCH}
          element={
            <Layout title="Search" page={Search} isHasNavigation={true} />
          }
        />
        <Route
          path={routes.FAVORITE}
          element={
            <Layout title="Favorite" page={Favorite} isHasNavigation={true} />
          }
        />
        <Route
          path={routes.DETAIL}
          element={
            <Layout
              title={<HomeIcon />}
              page={Detail}
              isHasNavigation={false}
            />
          }
        />
        <Route
          path={routes.NOT_FOUND}
          element={
            <Layout
              title={<HomeIcon />}
              page={NotFound}
              isHasNavigation={false}
            />
          }
        />
      </Switch>
    </Suspense>
  );
};

export default memo(Routes);
