import * as types from "./types/user";
import { UserResultsType } from "utils/types";

type Action = {
  type: string;
  payload: boolean | UserResultsType;
};

export type initialState = {
  isLoading: boolean;
  data: UserResultsType | null;
};

const initState = {
  isLoading: false,
  data: null,
} as initialState;

const Search = (state = initState, action: Action) => {
  const { type, payload } = action;

  switch (type) {
    case types.USER_LOADING:
      return {
        ...state,
        isLoading: payload,
      };

    case types.USER_DATA:
      return {
        ...state,
        data: payload,
        isLoading: false,
      };

    default:
      return { ...state };
  }
};

export default Search;
