import { PaletteMode } from "@mui/material";

const getDesignTokens = (mode: PaletteMode) => ({
  palette: {
    mode,
    primary: {
      main: "#1976d2",
    },
    background: {
      ...(mode === "light"
        ? {
            default: "#fff",
            paper: "#fff",
          }
        : {
            default: "#000",
            paper: "#fff",
          }),
    },
    text: {
      ...(mode === "light"
        ? {
            primary: "#000",
            secondary: "#00000099",
          }
        : {
            primary: "#fff",
            secondary: "#fff",
          }),
    },
  },
});

const globalThemes = {
  boxShadow: {
    light: "0px -4px 4px rgba(0, 0, 0, 0.05)",
    dark: "0 -4px 4px hsl(0deg 0% 100% / 50%)",
  },
  border: {
    light: "1px solid #0000006B",
    dark: "1px solid #fff",
  },
  userItem: {
    boxShadow: {
      light: "0px 4px 4px rgba(0, 0, 0, 0.1)",
      dark: "0 4px 4px hsl(0deg 0% 100% / 30%)",
    },
  },
};

export { getDesignTokens, globalThemes };
