import * as types from "./types/search";
import { SearchResultsType } from "utils/types";

type Action = {
  type: string;
  payload: boolean | SearchResultsType;
};

type initialState = {
  isLoading: boolean;
  data: SearchResultsType | null;
};

const initState = {
  isLoading: false,
  data: null,
} as initialState;

const Search = (state = initState, action: Action) => {
  const { type, payload } = action;

  switch (type) {
    case types.SEARCHING:
      return {
        ...state,
        isLoading: payload,
      };

    case types.SEARCH_BY_USERNAME:
      return {
        ...state,
        data: payload,
        isLoading: false,
      };

    case types.RESET_SEARCH:
      return initState;

    default:
      return { ...state };
  }
};

export default Search;
